/**
 * Client-side PDF export utility using html2canvas-pro and jsPDF.
 * html2canvas-pro has native support for modern CSS color formats (lab, oklab, oklch)
 * generated by Tailwind CSS v4, completely eliminating the "unsupported color function lab" error.
 */

export interface PdfExportOptions {
  orientation?: "portrait" | "landscape";
  margin?: number;
  scale?: number;
}

export async function exportElementToPdf(
  element: HTMLElement,
  filename: string,
  options?: PdfExportOptions
): Promise<void> {
  if (typeof window === "undefined" || !element) {
    return;
  }

  // Dynamic import to prevent SSR evaluation errors
  const html2canvasModule = await import("html2canvas-pro");
  const html2canvas =
    typeof html2canvasModule === "function"
      ? html2canvasModule
      : html2canvasModule.default || html2canvasModule;

  const { jsPDF } = await import("jspdf");

  const resolvedFilename = filename.toLowerCase().endsWith(".pdf")
    ? filename
    : `${filename}.pdf`;

  // Render element to canvas using html2canvas-pro (native support for lab, oklch, rgb, hex)
  const canvas = await html2canvas(element, {
    scale: options?.scale ?? 2,
    useCORS: true,
    logging: false,
    backgroundColor: "#ffffff",
    windowWidth: element.scrollWidth || 800,
  });

  const imgData = canvas.toDataURL("image/jpeg", 0.98);

  const orientation = options?.orientation ?? "portrait";
  const pdf = new jsPDF({
    orientation,
    unit: "mm",
    format: "a4",
  });

  // A4 dimensions in mm: 210 x 297 (portrait) or 297 x 210 (landscape)
  const pageWidth = orientation === "portrait" ? 210 : 297;
  const pageHeight = orientation === "portrait" ? 297 : 210;
  const margin = options?.margin ?? 8;

  const printableWidth = pageWidth - margin * 2;
  const printableHeight = (canvas.height * printableWidth) / canvas.width;

  let heightLeft = printableHeight;
  let position = margin;

  pdf.addImage(imgData, "JPEG", margin, position, printableWidth, printableHeight);
  heightLeft -= (pageHeight - margin * 2);

  while (heightLeft > 0) {
    position = heightLeft - printableHeight + margin;
    pdf.addPage();
    pdf.addImage(imgData, "JPEG", margin, position, printableWidth, printableHeight);
    heightLeft -= (pageHeight - margin * 2);
  }

  pdf.save(resolvedFilename);
}
